INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (5,'Hướng dẫn tính giá cước phí vận chuyển hàng hóa từ Sài Gòn đi Phú Quốc','\"<table style=\\\"width: 1697px; text-align: center; height: 218px;\\\">\\n \\n \\n <tbody><tr>\\n  <td style=\\\"background-color: rgb(234, 153, 153);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong style=\\\"font-size: 12px; font-family: Arial, Helvetica, sans-serif;\\\">STT</strong></span><div style=\\\"color:rgba(0,0,0,0.01);width:0;height:0\\\">&nbsp;<br></div></td>\\n  <td style=\\\"background-color: rgb(234, 153, 153);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong style=\\\"font-size: 12px; font-family: Arial, Helvetica, sans-serif;\\\">&nbsp;DIỄN\\n  GIẢI CHI PHÍ SÀI GÒN ĐI PHÚ QUỐC</strong></span></td>\\n  <td style=\\\"background-color: rgb(234, 153, 153);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong style=\\\"font-size: 12px; font-family: Arial, Helvetica, sans-serif;\\\">THÀNH\\n  TIỀN</strong></span></td>\\n </tr>\\n <tr>\\n  <td><span style=\\\"font-size: 12px;\\\">1</span></td>\\n  <td style=\\\"text-align: left;\\\"><span style=\\\"font-size: 12px;\\\">Phí lấy hàng tận nơi SÀI GÒN\\n  [nếu có]</span></td>\\n  <td><span style=\\\"font-size: 12px;\\\">...</span></td>\\n </tr>\\n <tr>\\n  <td><span style=\\\"font-size: 12px;\\\">2</span></td>\\n  <td style=\\\"text-align: left;\\\"><span style=\\\"font-size: 12px;\\\">Phí bốc xếp [hoặc xe cẩu]\\n  tại nơi gửi [nếu có]</span></td>\\n  <td><span style=\\\"font-size: 12px;\\\">...</span></td>\\n </tr>\\n <tr>\\n  <td style=\\\"background-color: rgb(239, 239, 239);\\\"><span style=\\\"font-size: 12px;\\\">3</span></td>\\n  <td style=\\\"text-align: left; background-color: rgb(239, 239, 239);\\\"><span style=\\\"color: rgb(255, 0, 0); font-size: 12px;\\\">Cước phí vận chuyển từ SÀI\\n  GÒN đi PHÚ QUỐC</span></td>\\n  <td style=\\\"background-color: rgb(239, 239, 239);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong style=\\\"color: rgb(255, 0, 0); font-size: 12px; font-family: Arial, Helvetica, sans-serif;\\\">...</strong></span><div style=\\\"color:rgba(0,0,0,0.01);width:0;height:0\\\">&nbsp;<br></div></td>\\n </tr>\\n <tr>\\n  <td><span style=\\\"font-size: 12px;\\\">4</span></td>\\n  <td style=\\\"text-align: left;\\\"><span style=\\\"font-size: 12px;\\\">Phí giao tận nơi PHÚ QUỐC\\n  [nếu có]</span></td>\\n  <td><span style=\\\"font-size: 12px;\\\">...</span></td>\\n </tr>\\n <tr>\\n  <td><span style=\\\"font-size: 12px;\\\">5</span></td>\\n  <td style=\\\"text-align: left;\\\"><span style=\\\"font-size: 12px;\\\">Phí bốc xếp [hoặc xe cẩu]\\n  tại nơi đến [nếu có]</span></td>\\n  <td><span style=\\\"font-size: 12px;\\\">...</span></td>\\n </tr>\\n <tr>\\n  <td><span style=\\\"font-size: 12px;\\\">6</span></td>\\n  <td style=\\\"text-align: left;\\\"><span style=\\\"font-size: 12px;\\\">Phí đóng gói hàng hóa [nếu\\n  có]</span></td>\\n  <td><span style=\\\"font-size: 12px;\\\">...</span></td>\\n </tr>\\n <tr>\\n  <td style=\\\"background-color: rgb(243, 243, 243);\\\"><span style=\\\"font-size: 12px;\\\">7</span></td>\\n  <td style=\\\"background-color: rgb(243, 243, 243);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong style=\\\"font-size: 12px; font-family: Arial, Helvetica, sans-serif;\\\">TỔNG SỐ TIỀN PHẢI THANH TOÁN&nbsp;[1+2+3+4+5+6 = tổng cước]</strong></span></td>\\n  <td style=\\\"background-color: rgb(243, 243, 243);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong style=\\\"font-size: 12px; font-family: Arial, Helvetica, sans-serif;\\\">Số tiền ......</strong></span></td>\\n </tr>\\n <tr>\\n  <td colspan=\\\"3\\\"><span style=\\\"font-size: 12px;\\\"><strong>Mục số 3 cần lưu ý:</strong> nếu là hàng nặng thì lấy [số kg * đơn giá], nếu là hàng nhẹ thì\\n  hãy lấy [số khối * đơn giá]<br></span></td></tr></tbody></table>\"');
