INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (11,'Quy định chung áp dụng kèm theo bảng giá cho thuê xe cẩu tại Phú Quốc','\"<table class=\\\"MsoNormalTable\\\" border=\\\"0\\\" cellpadding=\\\"0\\\" style=\\\"text-align: justify;\\\">\\n <tbody><tr>\\n  <td style=\\\"padding: 1px; width: 4.47562%; text-align: center; background-color: rgb(255, 153, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; line-height: normal;\\\"><strong face=\\\"Arial, Helvetica, sans-serif\\\"><span style=\\\"font-size: 14px;\\\">Stt</span></strong></p>\\n  <div style=\\\"color:rgba(0,0,0,0.01);width:0;height:0\\\"><span style=\\\"font-size: 14px;\\\">&nbsp;<br></span></div></td>\\n  <td colspan=\\\"2\\\" style=\\\"padding: 1px; background-color: rgb(255, 153, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Một số nội dung\\n  chi tiết được áp dụng riêng cho dịch vụ cho thuê xe cẩu tại Phú Quốc</span></strong></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">1</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; width: 10.8216%; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thuế GTGT</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đơn giá trên chưa\\n  thuế GTGT theo quy định của Bộ Tài Chính</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí xăng dầu nhớt\\n  vận hành cẩu</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Giá đã bao gồm vào\\n  bảng giá [không bao gồm trường hợp tăng ca]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">3</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Giờ hoạt động</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px; text-align: justify;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối với hình thức\\n  thuê xe cẩu theo đơn hàng: giờ nào cũng được phục vụ; Đối với thuê ca hay\\n  thuê tháng: sẽ được áp dụng 1 ca = 8 giờ [trong đó có 1 giờ ngủ trưa cho nhân\\n  viên]; sau 17h chiều hằng ngày sẽ được tính là giờ tăng ca làm việc.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">4</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Nhân công phục vụ\\n  xe cẩu dưới 7 tấn</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đã bao gồm 1 tài\\n  công có chứng chỉ vận hành xe cẩu</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">5</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Nhân công phục vụ\\n  xe cẩu 8 tấn - 20 tấn</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đã bao gồm 1 tài\\n  công có chứng chỉ vận hành xe cẩu và 1 nhân công phục vụ móc dây cẩu [phụ xe\\n  cẩu]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">6</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Nhân công phục vụ\\n  xe cẩu 8 tấn - 20 tấn</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đã bao gồm 1 tài\\n  công có chứng chỉ vận hành xe cẩu và 1 nhân công phục vụ móc dây cẩu [phụ xe\\n  cẩu] và cần 1 hoặc nhiều người hỗ trợ tại vị trí làm việc do bên thuê chịu\\n  phí tùy theo nhu cầu vận hành xe cẩu kato</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">7</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Trọng lượng hàng\\n  hóa</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối với việc thuê\\n  xe cẩu theo từng chuyến, theo từng đơn hàng hay theo một lô hàng nào đó, thì\\n  giá trên chỉ áp dụng cho những kiện hàng nhỏ có trọng lượng dưới 2 tấn/kiện.\\n  Nếu trọng lượng lớn hơn 2 tấn/kiện sẽ có phụ thu thêm phí điều động xe cẩu có\\n  tải trọng lớn để phục vụ Quý khách hàng.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">8</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Vị trí tốt cho xe\\n  cẩu</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Với những đơn hàng\\n  nhỏ lẻ cẩu theo chuyến, thì giá trên mặc định là giá cẩu ở vị trí 2 xe cẩu\\n  đứng sát vào nhau được, xe cẩu có trách nhiệm cẩu hạ từ xe tải xuống đất.\\n  Không bao gồm phí di chuyển hàng hóa theo yêu cầu. </span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">9</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phạm vi hoạt động</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đơn hàng nhỏ là sẽ\\n  được hiểu là hàng hạ từ xe tải lớn xuống đất hoặc từ dưới đất lên xe tải lớn,\\n  bán kính hoạt động của xe cẩu nhỏ thường là trong phạm vị 10m kể từ vị trí 2\\n  xe đậu được sát vào nhau.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">10</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Trung chuyển phát\\n  sinh</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Giá trên sẽ được\\n  phục vụ cho việc cẩu hàng lên xe hoặc cẩu hàng từ xe xuống đất, nếu phải di\\n  chuyển từ vị trí xe cẩu đậu được đi nơi khác trong bán kính 1km - 2km thì sẽ\\n  phụ thu thêm 50% số tiền ở bảng giá trên. Nếu di chuyển xa hơn sẽ được thỏa\\n  thuận khi có thực tế phát sinh.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">11</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Xe cẩu di chuyển\\n  hàng</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối với việc thuê\\n  cẩu từ công trình này qua công trình khác, hay đi đâu đó trong phạm vi của\\n  đảo Phú Quốc thì giá trên nhân gấp đôi = giá vận hành cho một chuyến xe cẩu\\n  chở hàng.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td style=\\\"padding: 1px; text-align: center;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">12</span></p>\\n  </td>\\n  <td style=\\\"padding: 1px; color: rgb(255, 0, 0);\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><strong><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí lưu xe cẩu</span></strong></p>\\n  </td>\\n  <td style=\\\"padding: 1px;\\\">\\n  <p class=\\\"MsoNormal\\\" style=\\\"margin: 0in; font-family: &quot;Times New Roman&quot;, serif; line-height: normal; font-size: 19px;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Xe cẩu loại dưới\\n  10 tấn = 1.500.000d/đêm; xe cẩu loại dưới 20 tấn = 2.000.000d/đêm; xe cẩu\\n  kato = 3.000.000d/đêm</span></p>\\n  </td>\\n </tr>\\n</tbody></table>\"');
INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (12,'Một số quy định kèm theo báo giá vận chuyển hàng hóa đi Phú Quốc','\"<table style=\\\"width: 1698px; height: 1973px; margin-left: 0.155642%;\\\">\\n <tbody><tr>\\n  <td style=\\\"background-color: rgb(255, 153, 0);\\\"><strong style=\\\"font-family: Arial, Helvetica, sans-serif; color: rgb(67, 67, 67); font-size: 14px;\\\">Stt</strong></td>\\n  <td style=\\\"color: rgb(67, 67, 67); background-color: rgb(255, 153, 0); width: 12.0666%;\\\"><strong style=\\\"color: rgb(67, 67, 67); font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Nội dung</strong></td>\\n  <td style=\\\"text-align: justify; background-color: rgb(255, 153, 0); width: 82.1082%;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong style=\\\"color: rgb(67, 67, 67); font-size: 14px;\\\">Chi tiết quy định kèm theo báo giá vận chuyển</strong></span><div style=\\\"color:rgba(0,0,0,0.01);width:0;height:0\\\"><span style=\\\"font-size: 14px;\\\">&nbsp;<br></span></div></td>\\n </tr><tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">1</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thuế\\n  GTGT</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đơn\\n  giá trên chưa thuế GTGT theo quy định của Bộ Tài Chính</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hình\\n  thức thanh toán</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thanh\\n  toán đủ 100% ngay khi gửi hàng, ngay khi giao hàng hoặc các thỏa thuận khác\\n  căn cứ theo hợp đồng vận chuyển hàng hóa.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">3</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phương\\n  thức thanh toán</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Tiền\\n  mặt hoặc chuyển khoản</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">4</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Giá vận\\n  tải không bao gồm phí</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Bốc\\n  xếp tại nơi gửi hàng, bốc xếp tại nơi giao hàng, bồi dưỡng tại nơi gửi hàng,\\n  bồi dưỡng tại nơi giao hàng, phí ra vào bãi xe – bến xe, phí đi vào đường\\n  cấm, đường nhỏ hoặc đường bị lún phải phát sinh phí trung chuyển … (Nếu có\\n  phát sinh các chi phí này thì Người gửi chịu)</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">5</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hàng\\n  nặng hay Hàng nhẹ</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Làm\\n  sao để biết chính xác khi nào áp dụng giá hàng nặng hay hàng nhẹ Đó là lấy\\n  Trọng lượng hàng hóa * đơn giá theo kg = số tiền, sau đó lấy Số khối (M3) *\\n  Đơn giá theo M3 = Số tiền, khi đó so sánh hai số tiền này lại với nhau, Bên\\n  Vận Chuyển sẽ áp dụng Đơn giá có số tiền cao nhất, Nếu số tiền cao nhất thuộc\\n  về cách tính Đơn giá * m3 thì được gọi là hàng nhẹ, nếu số tiền cước cao nhất\\n  thuộc về cách tính Đơn giá * Số kg thì được gọi là hàng nặng.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">6</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Quy đổi\\n  số khối</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Cách\\n  tính số khối: Dài * Rộng * Cao = Số khối (M3) (lưu ý: đơn vị tính là mét)</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">7</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hàng nhỏ\\n  lẻ phát sinh tăng</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối\\n  với trường hợp hàng lẻ mà chiếm tới trên 80% diện tích xe thì được tính giá\\n  nguyên xe, áp dụng theo khung giá bên trên.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">8</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hàng có\\n  kích thước lớn</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối\\n  với hàng có số khối nhỏ (ít) mà chiếm nhiều diện tích chiều dài của xe thì đo\\n  kích thước thùng xe để tính ra số khối, dùng số khối đo thùng xe tính ra được\\n  [dài xe * rộng xe * cao xe = số khối của thùng xe] để tính chi phí vận chuyển\\n  (số khối thùng xe&nbsp; * đơn giá cước phí vận chuyển = số tiền phải thanh\\n  toán)</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">9</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hàng\\n  không xếp chồng lên nhau</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Trường\\n  hợp đối với hàng hóa mà không xếp chồng lên nhau được, hoặc không xếp các\\n  hàng hóa khác bên trên được thì sẽ áp dụng cách tính khối là chiều dài *\\n  chiều rộng * cao 2.3m [mặc định cao tới nốc xe là 2.3m] = số khối để tính giá\\n  cước vận chuyển.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">10</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hàng\\n  không được để gần nhau</span></p>\\n  <div style=\\\"color:rgba(0,0,0,0.01);width:0;height:0\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">&nbsp;<br></span></div></td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Trường\\n  hợp đối với các loại hàng hóa không xếp gần nhau, sát nhau được, nếu sát nhau\\n  sẽ bị vỡ hay bi hư hỏng thì sẽ được áp dụng cách tính giá quy đổi số khối của\\n  xe tải lớn để tính giá cước vận chuyển bằng công thức [số khối = dài thực tế\\n  * rộng 2.3m * cao 2.3m]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">11</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Gửi hàng\\n  đi ghép xe tải</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hình\\n  thức vận chuyển hàng hóa đi ghép kết hợp nhiều lô hàng trên cùng một xe tải,\\n  Bảng giá trên không bao gồm phí lấy hàng tận nơi. Phí lấy tận nơi hãy xem phụ\\n  lục phí lấy hàng ở các khu vực cuối báo giá này.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">12</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Loại xe\\n  tải nhỏ tại Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí\\n  trung chuyển cho các đơn hàng nhỏ lẻ tại đảo Phú Quốc có 2 dòng xe tải loại 1\\n  tấn [dài 2.5m rộng 1.3m cao 1.5m], loại xe 2 tấn [dài 4.2m rộng 1.7m cao\\n  1.8m]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">13</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Bao xe\\n  chở hàng</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Chành\\n  xe Phú Quốc công ty Con Rùa Biển sẽ điều xe lấy hàng tận nơi tại nơi gửi,\\n  giao hàng tận nơi tại nơi đến [căn cứ theo \\\"PHIẾU XÁC NHẬN VẬN\\n  CHUYỂN\\\" đã được ký thỏa thuận trước khi vận chuyển.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">14</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Quy định\\n  \\\"Một-Một\\\"</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối\\n  với hàng thỏa thuận giao nhận tận nơi thì sẽ được hiểu là lấy 1 địa chỉ và\\n  giao 1 địa chỉ, nếu phát sinh từ 2 địa chỉ trở lên mà không được thỏa thuận\\n  trước thì mỗi địa chỉ giao nhận tận nơi là cộng thêm phí thấp nhất\\n  1.000.000đ/địa chỉ/xe tải (xe đầu kéo là 2.000.000đ/xe/địa chỉ)</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">15</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hủy xe</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối\\n  với trường hợp xe tải của Bên Vận Chuyển đã đến nơi gửi hàng (nơi đi) theo\\n  yêu cầu của Bên Thuê Vận Chuyển nhưng vì bất kỳ lý do nào đó mà Bên Vận\\n  Chuyển không có hàng để vận chuyển thì Bên Thuê Vận Chuyển sẽ phải chịu phí\\n  xăng dầu để Bên Vận Chuyển quay về là 2.000.000đ/xe tải/lần (xe đầu kéo là\\n  3.000.000đ/xe/lần).</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">16</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Lưu xe</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí\\n  lưu xe được tính phát sinh 1.500.000đ/đêm/xe tải (phát sinh 2.500.000đ/đêm/xe\\n  đầu kéo) áp dụng từ khi xe của Bên Vận Chuyển đến công trình (hoặc nơi giao\\n  hàng theo chỉ định) mà Bên Thuê Vận Chuyển không xuống được hàng với bất kỳ\\n  lý do nào đó mà xe Bên Vận Chuyển phải nằm lại qua đêm. Trường hợp [hàng nhỏ\\n  lẻ dưới 5 tấn] đặt biệt sẽ áp dụng phí lưu xe là 500.000 đ/xe/2 giờ.</span></p>\\n  </td>\\n </tr><tr>\\n  <td><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">`17</span></td>\\n  <td colspan=\\\"2\\\" style=\\\"color: rgb(255, 0, 0);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\"><span><em>Đối\\nvới hàng Container Xuất Nhập Khẩu đi Phú Quốc</em></span><br></span></td>\\n  \\n </tr>\\n \\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.1</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí\\n  Container</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Các\\n  chi phí nâng hạ tại cảng, lưu cont, cược cont, vệ sinh Cont... Chủ hàng (hoặc\\n  người gửi hàng) chịu các phí này.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.2</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\"><span style=\\\"font-size: 14px;\\\">\\n  \\n  Loại trừ</span></td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Cont\\n  đi từ Cảng Sài Gòn [hoặc các cảng lân cận HCM] đến Phú Quốc và quay về nếu\\n  sàn cont bị hư hỏng thì bên vận chuyển không bồi thường (Vì cont đi qua đảo\\n  Phú Quốc để lấy được hàng ra khỏi cont thì chỉ có dùng xe cẩu kéo ra, phương\\n  án này làm cho sàn cont bị hư thường xuyên)</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.3</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Miễn phí\\n  trả rỗng</span></p>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\"><span>&nbsp;</span><br></span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối\\n  với hàng nhập từ nước ngoài về, giá vận chuyển container đi Phú Quốc đã bao\\n  gồm phí lấy Container tại các Cảng ở Sài Gòn và vận chuyển Cont ra đảo Phú\\n  Quốc, đợi rút hàng xong, sẽ đem Container rỗng về trả lại Cảng ở khu vực HCM.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.4</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thời\\n  gian vận chuyển container</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Container\\n  hàng nhập từ Cảng ở Khu Vực HCM đi Phú Quốc giao tận nơi chỉ mất 1 ngày, tức\\n  là Hôm nay kéo container đi Phú Quốc thì ngày mai giao hàng tận nơi.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.5</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thời\\n  gian trả rỗng container</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thời\\n  gian vận chuyển Container nhập từ lúc đi đến lúc về luôn rơi vào khoảng 3-5\\n  ngày, do đó Quý Khách Hàng cần lưu ý làm lệnh nâng hạ cần dự trù thời gian\\n  trả rỗng bị chậm, để tránh tình trạng phải thay đổi lệnh nâng hạ trả rỗng tại\\n  Cảng và phát sinh phí thuê cont [từ lúc kéo đi đến lúc trả rỗng thường rơi\\n  vào khung 3-5 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.6</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Cho mượn\\n  cont mui bạc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Trong\\n  trường hợp Quý khách hàng có nhu cầu vận chuyển container mà không có cont\\n  thì bên vận chuyển sẽ cung cấp cont 40f để vận chuyển, loại cont dài 12m, có\\n  phủ bạc, miễn phí cho thuê cont để chở hàng.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.7</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Điều\\n  kiện giao nhận container</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Khi\\n  hàng hóa (hoặc container) đến nơi còn nguyên Seal (hoặc niêm phong) thì Bên\\n  Vận Chuyển đã hoàn thành trách nhiệm vận chuyển. Bên Vận Chuyển không chịu\\n  bất kỳ trách nhiệm bồi thường nào khi hàng hóa được giao bằng Container còn\\n  nguyên Seal, sau đó cắt Seal ra mới phát hiện bị hư hỏng hoặc mất mát.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">17.8</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hủy xe\\n  container đột xuất</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối\\n  với trường hợp xe đầu kéo của Bên Vận Chuyển đã đến nơi gửi hàng (nơi lấy\\n  container) theo yêu cầu của Bên Thuê Vận Chuyển, mà vì bất kỳ lý do nào đó mà\\n  Bên Thuê Vận Chuyển không có hàng container để vận chuyển thì Bên Thuê Vận\\n  Chuyển sẽ phải chịu phí xăng dầu để Bên Vận Chuyển quay về là\\n  3.000.000đ/xe/lần.</span></p>\\n  </td>\\n </tr><tr>\\n  <td><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18</span></td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\" colspan=\\\"2\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\"><em>Thời\\n  gian vận chuyển hàng nhanh ở một số khu vực</em><br></span></td>\\n  \\n </tr>\\n \\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.1</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Hà Nội -\\n  Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">4-7\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  <div style=\\\"color:rgba(0,0,0,0.01);width:0;height:0\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">&nbsp;<br></span></div></td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.2</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đà Nẵng\\n  - Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">3-5\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.3</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Quy Nhơn\\n  - Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2-4\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.4</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Nha\\n  Trang - Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">1-3\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.5</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Sài Gòn\\n  - Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">1-2\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.6</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Cần Thơ\\n  - Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">1-2\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.7</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đà Lạt -\\n  Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2-4\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.8</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Sài Gòn\\n  - Hà Nội</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">3-4\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.9</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Sài Gòn\\n  - Đà Nẵng</span></p>\\n  \\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2-3\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.10</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Sài Gòn\\n  - Cần Thơ</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">01\\n  Ngày</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.11</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Sài Gòn\\n  - Miền Bắc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">3-7\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.12</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Sài Gòn\\n  - Miền Trung</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2-4\\n  Ngày [ngược lại chậm hơn 1-2 ngày]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">18.13</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Sài Gòn\\n  - Miền Tây</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">01\\n  Ngày</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">19</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Bốc xếp\\n  bằng tay tại Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Chi\\n  phí nhân công bốc xếp hàng hóa bằng tay tại Phú Quốc [hàng nặng = 150.000\\n  đ/tấn]; [hàng nhẹ = 2.000.000d/xe tải 15 tấn chở hàng dưới 5 tấn đầy xe]\\n  (trọng lượng hàng hóa bốc xếp bằng tay được quy định không quá 50kg/kiện),\\n  khoãng cách bốc xếp được tính từ vị trí xe đậu được trong bán kính &lt;10m,\\n  nếu khoãng cách xa hơn 10m thì cứ mỗi 10m phát sinh là 1.000.000đ/10m/xe tải\\n  &lt;15 tấn, nếu trên 50m thì sẽ được đàm phán chi phí bốc xếp theo thỏa thuận\\n  khác. [trường hợp đặt biệt đối với mặt hàng hóa chất sẽ được tính giá gấp đôi\\n  hoặc từ chối bốc xếp bằng tay vì lý do sức khỏe và chất độc hại của hóa chất]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">20</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Xe cẩu\\n  tại Phú Quốc</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Chi\\n  phí cho thuê xe cẩu tại Phú Quốc được tính như sau: Cẩu hàng từ dưới đất lên\\n  xe tải hoặc từ xe tải xuống đất loại xe tải 15 tấn = 2.000.000đ/xe địa chỉ;\\n  loại xe tải 19 tấn = 3.000.000đ/xe/địa chỉ; xe đầu kéo = 4.000.000đ/xe/địa\\n  chỉ [Quy định chung chung cho các loại hàng hóa: kiện hàng nặng &lt;2\\n  tấn/kiện, số lượng &lt;20 kiện/xe; nếu nặng hơn hoặc quá nhiều kiện hàng thì\\n  chi phí xe cẩu sẽ bị tăng giá; Vị trí cẩu lên xe hoặc hạ xuống là vị trí\\n  thuận lợi, xe tải và xe cẩu đậu sát vào nhau để thực hiện tốt được các công\\n  việc; cần phải đặt lịch hẹn cẩu hạ trước để được sắp xếp hợp lý nhất]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">21</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Bảo hiểm\\n  hàng hóa có giá trị cao</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí\\n  bảo hiểm hàng hóa có giá trị cao hiện tại chung chung cho các mặt hàng trên\\n  thị trường là 0.1%/giá trị cần mua bảo hiểm (tức là 1 tỷ = phí bảo hiểm 1\\n  triệu đồng); phí mua bảo hiểm cho hàng hóa giá trị cao Người gửi chịu hoặc\\n  thỏa thuận khác theo hợp đồng vận chuyển đã ký.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">22</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí thu\\n  hộ [COD]</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thu\\n  hộ tiền bán hàng sẽ không bị tính phí, nhưng phí chuyển khoản trả lại tiền\\n  thu hộ cho mỗi đơn hàng là 50.000đ. Số tiền này sẽ bị trừ vào số tiền thu\\n  được. [số tiền thu hộ sẽ được Con Rùa Biển chuyển khoản trả lại khách hàng\\n  vào thứ 3 hàng tuần; nếu số tiền thu hộ &gt;50 triệu/lần thì Bên Vận Chuyển\\n  sẽ yêu cầu Người mua [Người nhận hàng tại Phú Quốc] chuyển khoản cho Người\\n  bán khi giao hàng tại thời điểm giao hàng theo số tài khoản đã được Người gửi\\n  hàng chỉ định theo thỏa thuận ban đầu]</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">23</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí giao\\n  nhận hàng dài &gt;4m</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối\\n  với hàng hóa có kích thước chiều dài trên 4m thì phải dùng xe tải lớn để giao\\n  nhận 2 đầu, do vậy Phụ phí bổ sung cho việc đi lấy hàng nếu có là cộng thêm\\n  500.000d/lượt, và phí đi giao tận nơi tại Phú Quốc cũng sẽ được cộng thêm vào\\n  phí giao 500.000d/lượt.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">24</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phụ lục\\n  chi tiết phí lấy hàng tận nơi</span></p>\\n  </td>\\n  <td style=\\\"text-align: justify;\\\">\\n  <p><span><a href=\\\"https://conruabien.vn/phu-phi-giao-nhan-hang-tan-noi/\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">https://conruabien.vn/phu-phi-giao-nhan-hang-tan-noi/</span></a></span></p>\\n  </td>\\n </tr>\\n</tbody></table>\\n\"');
INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (13,'2.1 Bảng giá vận chuyển hàng nặng từ HÀ NỘI Đi PHÚ QUỐC [Giao nhận hàng nhanh]','\"<table border=\\\"0\\\" cellpadding=\\\"0\\\" cellspacing=\\\"0\\\" width=\\\"509\\\" style=\\\"text-align: center; width: 100%; height: 668px;\\\">\\n\\n\\n\\n\\n    <tbody>\\n        <tr height=\\\"37\\\">\\n            <td height=\\\"37\\\" class=\\\"xl67\\\" width=\\\"183\\\" style=\\\"background-color: rgb(109, 158, 235);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong>Trọng\\n                Lượng (Kg)</strong></span></td>\\n            <td class=\\\"xl67\\\" width=\\\"155\\\" style=\\\"background-color: rgb(109, 158, 235);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong>Đơn Giá Hàng\\n                Nặng</strong></span></td>\\n            <td class=\\\"xl67\\\" width=\\\"171\\\" style=\\\"background-color: rgb(109, 158, 235);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\"><strong>Phí Giao Tận\\n                Nơi</strong></span></td>\\n        </tr>\\n        <tr height=\\\"33\\\">\\n            <td height=\\\"33\\\" class=\\\"xl68\\\" style=\\\"text-align: center;\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">&gt;= \\n                50kg\\n            </span></td>\\n            <td class=\\\"xl69\\\" width=\\\"155\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">330,000\\n                đ/kiện</span></td>\\n            <td class=\\\"xl70\\\" width=\\\"171\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">150,000\\n                vnđ/địa chỉ</span></td>\\n        </tr>\\n        <tr height=\\\"33\\\">\\n            <td height=\\\"33\\\" class=\\\"xl71\\\" style=\\\"background-color: rgb(201, 218, 248);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">51 - 100Kg</span></td>\\n            <td class=\\\"xl72\\\" width=\\\"155\\\" style=\\\"background-color: rgb(201, 218, 248);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">6,000\\n                đ/kg</span></td>\\n            <td class=\\\"xl74\\\" width=\\\"171\\\" style=\\\"background-color: rgb(201, 218, 248);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">200,000\\n                vnd/địa chỉ</span></td>\\n        </tr>\\n        <tr height=\\\"33\\\">\\n            <td height=\\\"33\\\" class=\\\"xl71\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">101 - 200Kg</span></td>\\n            <td class=\\\"xl72\\\" width=\\\"155\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">5,600\\n                đ/kg</span></td>\\n            <td class=\\\"xl70\\\" width=\\\"171\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">250,000\\n                vnđ/địa chỉ</span></td>\\n        </tr>\\n        <tr height=\\\"33\\\">\\n            <td height=\\\"33\\\" class=\\\"xl71\\\" style=\\\"background-color: rgb(201, 218, 248);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">201 - 500Kg</span></td>\\n            <td class=\\\"xl72\\\" width=\\\"155\\\" style=\\\"background-color: rgb(201, 218, 248);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">5,200\\n                đ/kg</span></td>\\n            <td class=\\\"xl74\\\" width=\\\"171\\\" style=\\\"background-color: rgb(201, 218, 248);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">300,000\\n                vnd/địa chỉ</span></td>\\n        </tr>\\n        <tr height=\\\"33\\\">\\n            <td height=\\\"33\\\" class=\\\"xl71\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 12px;\\\">501 - 750Kg</span></td