INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (49,'XM1. Bảng giá Chành xe Vận chuyển Xe Máy từ Hà Nội đi Sài Gòn [và Ngược lại]','\"<table style=\\\"text-align: center; width: 100%; height: 57px;\\\"><tbody><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(109, 158, 235);\\\"><strong>Loại Xe Máy</strong></td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(109, 158, 235);\\\"><strong>Hà Nội đi HCM</strong></td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(109, 158, 235);\\\"><strong>HCM đi Hà Nội</strong></td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe máy cũ &lt; 10 triệu</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">1,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">1,300,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(201, 218, 248);\\\">Xe máy cũ 10tr - 20tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(201, 218, 248);\\\">1,200,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(201, 218, 248);\\\">1,500,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe máy cũ 21tr - 40tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">1,500,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">1,800,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(201, 218, 248);\\\">Xe máy cũ 51tr - 100tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(201, 218, 248);\\\">2,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(201, 218, 248);\\\">2,300,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe Mô Tô &gt;100tr - 500tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">3,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">3,500,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(201, 218, 248);\\\">Xe Mô Tô &gt;500tr - 1 Tỷ</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(201, 218, 248);\\\">3,500,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(201, 218, 248);\\\">4,000,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe Mô Tô &gt;01 Tỷ</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">4,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">4,500,000 vnđ/xe</td></tr></tbody></table>\"');
INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (50,'Một số quy định chung áp dụng kèm theo bảng giá chành xe vận chuyển xe máy','\"<table style=\\\"text-align: justify; width: 1289px; height: 537px;\\\">\\n <tbody><tr>\\n  <td style=\\\"background-color: rgb(255, 153, 0);\\\"><strong face=\\\"Arial, Helvetica, sans-serif\\\"><span style=\\\"font-size: 14px;\\\">Stt</span></strong></td>\\n  <td colspan=\\\"2\\\" style=\\\"background-color: rgb(255, 153, 0);\\\"><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\"><strong>Một số nội dung chi tiết được áp dụng riêng cho xe máy khi vận chuyển</strong><br></span></td>\\n  \\n </tr><tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">1</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Thuế GTGT</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đơn giá trên chưa thuế\\n  GTGT theo quy định của Bộ Tài Chính</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Bao bọc xe máy</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Giá vận chuyển không bao gồm phí đóng gói, phí\\n  bao bọc hay phí bảo quản xe tuyệt đối.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">3</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Lưu giữ xe máy</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Khách hàng khi gửi xe máy trong hệ thống Con\\n  Rùa Biển sẽ được miễn phí lưu kho 2 đầu gửi và nhận xe, mỗi đầu được miễn phí\\n  5 ngày lưu xe, nên khách hàng khi nào rảnh thì có thể sắp xếp thời gian phù\\n  hợp ra kho bãi xe để giao nhận xe.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">4</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Bảo hiểm xe máy giá trị cao</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đối với xe máy có giá trị Quý khách hàng nên\\n  mua bảo hiểm cho hàng hóa giá trị cao, phí bảo hiểm hàng giá trị cao [là\\n  0.1%/giá trị bảo hiểm], phí bảo hiểm thấp nhất cho mỗi đơn hàng là 500.000\\n  vnđ.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">5</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí đóng gói xe</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Quý khách hàng có thể lựa chọn bất ký phương\\n  pháp đóng gói nào bên dưới hoặc có thể yêu cầu đóng gói cao cấp hơn vẫn được\\n  Con Rùa Biển phục vụ đáp ứng.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">6</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Miễn phí</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đóng gói bằng màng co và băng keo</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">7</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0); text-align: right;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí 100.000 vnđ</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Vật tư đóng gói là thùng carton và băng keo để\\n  quấn lại xung quanh xe.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">8</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0); text-align: right;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí 200.000 vnđ</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Vật tư đóng gói là thùng carton, băng keo, xốp\\n  hơi để quấn lại xung quanh xe.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">9</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0); text-align: right;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí 300.000 vnđ</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Vật tư đóng gói là thùng carton, băng keo, xốp\\n  hơi , màng co và vải mềm để quấn lại xung quanh xe.</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">10</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Phí đóng kiện gỗ</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Đề nghị khách hàng nên đóng kiện gỗ đối với xe\\n  mô tô phân khối lớn có giá trị cao</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">11</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0); text-align: right;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Xe số giá trị thấp</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">2.000.000 vnđ/xe</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">12</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0); text-align: right;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Xe tay ga giá trị cao</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">3.000.000 vnđ/xe</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">13</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0); text-align: right;\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Xe mô tô phân khối lớn</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">4.000.000 vnđ/xe</span></p>\\n  </td>\\n </tr>\\n <tr>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">14</span></p>\\n  </td>\\n  <td style=\\\"color: rgb(255, 0, 0);\\\">\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Bồi thường thiệt hại</span></p>\\n  </td>\\n  <td>\\n  <p><span style=\\\"font-family: Arial, Helvetica, sans-serif; font-size: 14px;\\\">Nếu trong quá trình vận chuyển những xe máy đã\\n  mua bảo hiểm hàng hóa giá trị cao sẽ được bồi thường 100% giá trị thiệt hại\\n  cho xe nếu có xảy ra rủi ro.</span></p>\\n  </td>\\n </tr>\\n</tbody></table>\"');
INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (51,'XM5. Bảng giá Chành xe Vận chuyển Xe Máy từ Sài Gòn đi Phú Quốc [và Ngược lại]','\"<table style=\\\"text-align: center; width: 100%; height: 107px;\\\"><tbody><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(230, 145, 56);\\\"><strong>Loại Xe Máy</strong></td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(230, 145, 56);\\\"><strong>HCM đi Phú Quốc</strong></td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(230, 145, 56);\\\"><strong>Phú Quốc đi HCM</strong></td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe máy cũ &lt; 10 Triệu</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">800,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">1,100,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(252, 229, 205);\\\">Xe máy cũ 10tr - 20tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">1,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">1,300,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe máy cũ 21tr - 40tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">1,300,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">1,600,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(252, 229, 205);\\\">Xe máy cũ 51tr - 100tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">1,800,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">2,100,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe Mô Tô &gt;100tr - 500tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">2,800,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">3,300,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(252, 229, 205);\\\">Xe Mô Tô &gt;500tr - 1 Tỷ</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">3,300,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">3,800,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe Mô Tô &gt;01 Tỷ</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">3,800,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">4,300,000 vnđ/xe</td></tr></tbody></table>\"');
INSERT INTO table_price (`id`,`title_table`,`content_table`) VALUES (52,'XM2. Bảng giá Chành xe Vận chuyển Xe Máy từ Hà Nội đi Phú Quốc [và Ngược lại]','\"<table style=\\\"text-align: center; width: 100%; height: 88px;\\\"><tbody><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(246, 178, 107);\\\"><strong>Loại Xe Máy</strong></td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(246, 178, 107);\\\"><strong>Hà Nội đi Phú Quốc</strong></td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(246, 178, 107);\\\"><strong>Phú Quốc đi Hà Nội</strong></td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe máy cũ &lt; 10 triệu<div style=\\\"color:rgba(0,0,0,0.01);width:0;height:0\\\">&nbsp;<br></div></td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">2,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">2,000,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(252, 229, 205);\\\">Xe máy cũ 10tr - 20tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">2,400,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">3,000,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe máy cũ 21tr - 40tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">3,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">3,500,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(252, 229, 205);\\\">Xe máy cũ 51tr - 100tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">4,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">4,500,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe Mô Tô &gt;100tr - 500tr</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">6,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">7,000,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left; background-color: rgb(252, 229, 205);\\\">Xe Mô Tô &gt;500tr - 1 Tỷ</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">7,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"background-color: rgb(252, 229, 205);\\\">8,000,000 vnđ/xe</td></tr><tr><td colspan=\\\"1\\\" rowspan=\\\"1\\\" style=\\\"text-align: left;\\\">Xe Mô Tô &gt;01 Tỷ</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">8,000,000 vnđ/xe</td><td colspan=\\\"1\\\" rowspan=\\\"1\\\">9,000,000 vnđ/xe</td></tr></tbody></table>\"');
